package com.company.platform.commerce.infrastructure.persistence;
import com.company.platform.commerce.domain.offer.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JdbcCommercialRuleRepository implements CommercialRuleRepository { private final JdbcTemplate jdbc; public JdbcCommercialRuleRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} public CommercialRule save(CommercialRule r){jdbc.update("INSERT INTO commercial_rules(id,tenant_id,name,description,type,status) VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=?,description=?,type=?,status=?,updated_at=CURRENT_TIMESTAMP",r.id(),r.tenantId(),r.name(),r.description(),r.type().name(),r.status(),r.name(),r.description(),r.type().name(),r.status());return r;} private CommercialRule map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new CommercialRule((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),r.getString("name"),r.getString("description"),CommercialRuleType.valueOf(r.getString("type")),r.getString("status"));} public List<CommercialRule> findAllByTenantId(UUID t){return jdbc.query("SELECT * FROM commercial_rules WHERE tenant_id=? ORDER BY created_at",this::map,t);}}
